begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(12);
insert into auth.users(id,email,raw_user_meta_data) values
 ('fb100000-0000-4000-8000-000000000001','quick-chaser@example.test','{"display_name":"Chaser test","age_confirmed":true}');
create temporary table chaser_state(key text primary key,value jsonb);
grant all on chaser_state to authenticated;
create function pg_temp.chaser_id(text) returns uuid language sql as $$select (value#>>'{}')::uuid from chaser_state where key=$1$$;
select set_config('request.jwt.claim.sub','fb100000-0000-4000-8000-000000000001',true);
set local role authenticated;
insert into chaser_state values('start',public.start_night_out_recoverable('fb500000-0000-4000-8000-000000000001','Chaser night',clock_timestamp()+interval '3 hours','UTC','[]','[]'));
insert into chaser_state select 'night',value->'nightId' from chaser_state where key='start';
insert into chaser_state select 'member',value#>'{snapshot,currentMemberId}' from chaser_state where key='start';
insert into chaser_state values('entries', jsonb_build_array(jsonb_build_object('id','fb300000-0000-4000-8000-000000000001','sessionId','fb400000-0000-4000-8000-000000000001','kind','chaser','recordedAt',clock_timestamp()-interval '1 hour','sequence',1,'revision',1)));
insert into chaser_state values('receipt',public.import_quick_log('fb600000-0000-4000-8000-000000000001','fb400000-0000-4000-8000-000000000001',pg_temp.chaser_id('night'),pg_temp.chaser_id('member'),(select value from chaser_state where key='entries')));
select extensions.is((select kind from public.quick_night_logs),'chaser','chaser imports as its own non-alcoholic kind');
select extensions.is((select count(*) from public.drink_logs),0::bigint,'chasers never create measured alcohol');
select extensions.is((select count(*) from public.water_logs),0::bigint,'unknown chaser size is not invented as measured water');
select extensions.is(public.get_night_snapshot(pg_temp.chaser_id('night'))#>>'{members,0,quickLogs,0,kind}','chaser','active snapshots retain chasers');
select extensions.is(public.import_quick_log('fb600000-0000-4000-8000-000000000001','fb400000-0000-4000-8000-000000000001',pg_temp.chaser_id('night'),pg_temp.chaser_id('member'),(select value from chaser_state where key='entries')),(select value from chaser_state where key='receipt'),'lost chaser import response reconciles exactly once');
select extensions.is((select count(*) from public.quick_night_logs),1::bigint,'reconciliation does not duplicate chasers');
select extensions.lives_ok($$select public.correct_quick_log((select id from public.quick_night_logs),'drink')$$,'can correct chaser to drink');
select extensions.lives_ok($$select public.correct_quick_log((select id from public.quick_night_logs),'chaser')$$,'can correct drink back to chaser');
select extensions.is((select source_kind from public.quick_night_logs),'chaser','correction retains original chaser provenance');
select public.end_night(pg_temp.chaser_id('night')) is not null;
select extensions.is(public.get_finished_nights(0)->0->>'quickChaserCount','1','finished history includes chasers separately');
select extensions.is(public.get_finished_nights(0)->0->>'quickDrinkCount','0','chasers never inflate the alcohol drink count');
select extensions.is(public.get_finished_night_summary(pg_temp.chaser_id('night'))#>>'{members,0,quickLogs,0,kind}','chaser','finished recap retains chaser-only activity');
select * from extensions.finish();
rollback;
